def get_synced_credential_status(
    self, tenant_id: str, issuer_did: str, credential_id: str
) -> CredentialStatusSyncRecord:
    """查询已同步的外部凭证状态。

    按本租户 (issuer_did, credential_id) 双键查找；未同步或属他租户
    均抛 NotFoundError（HTTP 404，跨租户不可探测）。
    """
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        row = None
        if bucket is not None:
            row = (
                bucket.get("credential_status_sync", {})
                .get(issuer_did, {})
                .get(credential_id)
            )
        if row is None:
            raise NotFoundError(
                "外部凭证状态未同步: "
                f"{issuer_did}#{credential_id}"
            )
        return self._sync_status_record(issuer_did, credential_id, row)

def get_credential_status_receipt_material(
    self,
    tenant_id: str,
    issuer_did: str,
    credential_id: str,
    verifier_did: str,
) -> Tuple[str, Optional[str], str, int, int, str]:
    """在同一把锁内原子读取凭证状态同步签名回执所需全部材料。

    - 本租户未同步该凭证（含属他租户）时抛
      NotFoundError("资源不存在")；
    - 验证者 DID 在本租户不存在（含跨租户）同样抛
      NotFoundError("资源不存在")；已停用抛
      ConflictError("验证者已停用")；
    - 原子取同步记录的 status/reason/updated_at/issuer_key_version
      与验证者当前密钥版本及托管私钥 PEM。

    返回 (status, reason, updated_at, issuer_key_version,
    verifier_key_version, verifier_private_pem)。
    纯只读：不写状态、历史或审计、不触发落盘；材料完全由持久化
    状态决定，重启后相同。
    """
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        row = None
        if bucket is not None:
            row = (
                bucket.get("credential_status_sync", {})
                .get(issuer_did, {})
                .get(credential_id)
            )
        if row is None:
            raise NotFoundError("资源不存在")

        verifier_rec = (
            bucket["dids"].get(verifier_did)
            if bucket is not None
            else None
        )
        if verifier_rec is None:
            raise NotFoundError("资源不存在")
        if verifier_rec.get("status") == "deactivated":
            raise ConflictError("验证者已停用")
        verifier_key_version = int(verifier_rec.get("key_version", 1))
        verifier_private_pem = self._private_key_for_version_locked(
            bucket, verifier_did, verifier_key_version
        )
        if not verifier_private_pem:
            # 正常不会发生：迁移保证当前版本私钥存在。
            raise NotFoundError("资源不存在")

        return (
            row["status"],
            row.get("reason"),
            row["updated_at"],
            int(row["issuer_key_version"]),
            verifier_key_version,
            verifier_private_pem,
        )

def list_synced_credential_status_history(
    self,
    tenant_id: str,
    issuer_did: str,
    credential_id: str,
    after: int = 0,
    limit: int = 50,
) -> Tuple[List[CredentialStatusHistoryEvent], int]:
    """查询某双键外部凭证的状态历史（只读），按页返回。

    - 双键在本租户未同步（含他租户）抛 NotFoundError（HTTP 404）；
    - 历史按 updated_at 升序、同 updated_at 按 cursor 升序排列；
    - 排除 cursor 不大于 after 的项，至多返回 limit 项；
    - next_after 为本页末项 cursor，空页保持 after。

    audit_seq 为 None 的兼容项（旧状态补录，无法追溯同步事件）
    仍照常按 cursor 返回。
    """
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        current_row = None
        entries: List[Dict[str, Any]] = []
        if bucket is not None:
            current_row = (
                bucket.get("credential_status_sync", {})
                .get(issuer_did, {})
                .get(credential_id)
            )
            entries = list(
                bucket.get("credential_status_history", {})
                .get(issuer_did, {})
                .get(credential_id, [])
            )
        if current_row is None:
            raise NotFoundError(
                "外部凭证状态未同步: "
                f"{issuer_did}#{credential_id}"
            )

        def sort_key(row: Dict[str, Any]) -> Tuple[datetime, int]:
            return (
                _parse_utc_z(row["updated_at"]),
                int(row["cursor"]),
            )

        ordered = sorted(entries, key=sort_key)
        picked: List[CredentialStatusHistoryEvent] = []
        for row in ordered:
            if len(picked) >= limit:
                break
            cursor = int(row["cursor"])
            if cursor <= after:
                continue
            picked.append(
                CredentialStatusHistoryEvent(
                    status=row["status"],
                    reason=row.get("reason"),
                    updated_at=row["updated_at"],
                    issuer_key_version=int(row["issuer_key_version"]),
                    cursor=cursor,
                    audit_seq=(
                        int(row["audit_seq"])
                        if row.get("audit_seq") is not None
                        else None
                    ),
                    audit_timestamp=(
                        int(row["audit_timestamp"])
                        if row.get("audit_timestamp") is not None
                        else None
                    ),
                )
            )
        next_after = picked[-1].cursor if picked else after
        return picked, next_after

